        "showWhen": {
          "parameter": "query_type",
          "value": [
            "entity-lookup",
            "network"
          ]
        }
      },
      {
        "name": "search_term",
        "type": "string",
        "required": false,
        "description": "Search term for finding entities",
        "placeholder": "e.g., breast cancer, alzheimer",
        "showWhen": {
          "parameter": "query_type",
          "value": "search"
        }
      },
      {
        "name": "limit",
        "type": "number",
        "required": false,
        "description": "Maximum number of results to return",
        "defaultValue": 50,
        "min": 1,
        "max": 1000,
        "showWhen": {
          "parameter": "query_type",
          "value": "search"
        }
      },
      {
        "name": "depth",
        "type": "number",
        "required": false,
        "description": "Network depth (number of relationship hops)",
        "defaultValue": 2,
        "min": 1,
        "max": 3,
        "showWhen": {
          "parameter": "query_type",
          "value": "network"
        }
      },
