        "min": 1,
        "max": 100,
        "showWhen": {
          "parameter": "query_type",
          "value": "network"
        }
      },
      {
        "name": "relationship_types",
        "type": "string",
        "required": false,
        "description": "Comma-separated relationship types to include (e.g., ENCODES,AFFECTS)",
