        "showWhen": {
          "parameter": "query_type",
          "value": "network"
        }
      },
      {
        "name": "expand",
        "type": "select",
        "required": false,
        "description": "Expand all relationships (removes pagination limits)",
        "options": [
          "all"
        ],
        "showWhen": {
          "parameter": "query_type",
          "value": "entity-lookup"
        }
      }
    ],
    "executionMode": "instant",
